// server.js -- no cors() middleware anywhere
const express = require('express');
const app = express();

app.get('/internal/data', (req, res) => {
  res.json({ value: 42 });
});

app.listen(4000);

const rateLimit = require('express-rate-limit');

const loginLimiter = rateLimit({
  windowMs: 60 * 60 * 1000,   // 1 hour
  max: 5,                      // 5 requests per window
  keyGenerator: (req) => req.ip,   // identifies clients by IP address
});

app.post('/login', loginLimiter, loginHandler);

exercises.solutionCode:
const rateLimit = require('express-rate-limit');

// Raise the per-IP ceiling to a level that tolerates a shared office
// network's realistic combined login volume, while still blocking a
// genuine rapid-fire brute-force burst from a single source.
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,   // shorter window
  max: 30,                     // enough headroom for many employees behind one IP
  keyGenerator: (req) => req.ip,
});

// A second, tighter limiter keyed on the attempted username specifically
// catches a real brute-force attempt against ONE account, regardless of
// how many unrelated users happen to share that account's IP.
const perAccountLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  keyGenerator: (req) => req.body.email || 'unknown',
});

app.post('/login', loginLimiter, perAccountLimiter, loginHandler);
